import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  const mainGroup = new Group();

  // Create absolute dark-first backdrop (7.5x6.0 at z=-2.5) to avoid any FLAT_VOID
  const backdropGeo = new PlaneGeometry(8.5, 6.5);
  const backdropMat = new MeshBasicNodeMaterial();
  const uvs = uv();
  // Engineered gradient using spec palette: ink (#16161d) to surface (#0b0b10)
  backdropMat.colorNode = mix(color('#16161d'), color('#0b0b10'), uvs.y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  mainGroup.add(backdrop);

  // Lighting setup for machined details and metallic reflection
  const ambient = new AmbientLight(0xffffff, 0.5);
  const keyLight = new DirectionalLight(0xe8ecf2, 1.2);
  keyLight.position.set(3, 4, 3);
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-3, -2, 2);
  mainGroup.add(ambient, keyLight, rimLight);

  // Card pivot for interactive offset
  const cardGroup = new Group();
  mainGroup.add(cardGroup);

  // Highlight border (accent edge on focus / hover)
  const borderGeo = new BoxGeometry(3.44, 2.24, 0.08);
  const borderMat = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    transparent: true,
    opacity: 0.2
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.set(0, 0, -0.01);
  cardGroup.add(borderMesh);

  // Main Card Body (Beveled feel and loaded image asset)
  const cardGeo = new BoxGeometry(3.4, 2.2, 0.1);
  const cardMat = new MeshStandardNodeMaterial({
    color: 0x16161d,
    roughness: 0.52,
    metalness: 0.5,
    clearcoat: 0.2
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardGroup.add(cardMesh);

  // Contact shadow underneath the card
  const shadowGeo = new PlaneGeometry(3.6, 0.3);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.55
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -1.2, 0.1);
  cardGroup.add(shadowMesh);

  // Safe Text bridging
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let quoteText = "“THE ATELIER REPRESENTS A SANCTUARY FOR CHRONOMETRIC PURITY.”";
  let authorText = "— NOVA JOURNAL";

  if (items.length > 0) {
    quoteText = items[0].text;
    if (items[1]) {
      authorText = items[1].text;
    }
  }

  // Create & mount text
  const quoteNode = ctx.fontAtlas.createText(quoteText, {
    fontSize: 0.13,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 640
  });
  quoteNode.position.set(0, 0.2, 0.07);
  cardGroup.add(quoteNode);

  const authorNode = ctx.fontAtlas.createText(authorText, {
    fontSize: 0.09,
    color: '#ff2a38',
    align: 'center',
    maxWidthPx: 500
  });
  authorNode.position.set(0, -0.4, 0.07);
  cardGroup.add(authorNode);

  // Interactive Animations (GSAP)
  const activeTimelines = [];

  const onOver = () => {
    const tl = gsap.timeline();
    tl.to(cardGroup.position, { y: 0.15, z: 0.1, duration: 0.4, ease: 'power2.out' }, 0);
    tl.to(borderMat, { opacity: 0.8, duration: 0.3 }, 0);
    tl.to(cardGroup.rotation, { x: 0.05, y: -0.05, duration: 0.4 }, 0);
    activeTimelines.push(tl);
  };

  const onOut = () => {
    const tl = gsap.timeline();
    tl.to(cardGroup.position, { y: 0, z: 0, duration: 0.5, ease: 'power3.out' }, 0);
    tl.to(borderMat, { opacity: 0.2, duration: 0.4 }, 0);
    tl.to(cardGroup.rotation, { x: 0, y: 0, duration: 0.5 }, 0);
    activeTimelines.push(tl);
  };

  const onClick = () => {
    const tl = gsap.timeline();
    tl.to(cardGroup.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.1, ease: 'power1.out' });
    tl.to(cardGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.2, ease: 'back.out(2)' });
    activeTimelines.push(tl);

    ctx.emit('hub-journal.select', { id: config.id });
  };

  // Bind custom Handlers
  mainGroup.userData.handlers = {
    pointerover: onOver,
    pointerout: onOut,
    click: onClick
  };

  // Cinematic Primitives
  const prims = [];
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    const p = ctx.primitives['parallax-scroll'](cardGroup, { intensity: 0.25 });
    if (p) prims.push(p);
  }

  // Cleanup
  mainGroup.userData.cleanup = () => {
    activeTimelines.forEach(tl => tl.kill());
    prims.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
    backdropGeo.dispose();
    backdropMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return mainGroup;
}
